import { createUuidV4Pipe } from '../../common/pipes/uuid-v4.pipe';

@Controller('contacts')
export class ContactController {
  constructor(private readonly contactService: ContactService) {}

  /**
   * Create a new contact
   * Endpoint: POST /contacts[cite: 1]
   */
  @Post()
  async create(@Body() createContactDto: CreateContactDto) {
    return await this.contactService.createContact(createContactDto);
  }

  /**
   * List contacts with pagination and filtering
   * Endpoint: GET /contacts[cite: 1]
   */
  @Get()
  async findAll(@Query() query: ContactListQueryDto) {
    return await this.contactService.getContactsList(query);
  }

  /**
   * Get a single contact by ID
   * Endpoint: GET /contacts/:id[cite: 1]
   * Note: ParseUUIDPipe enforces the 400 INVALID_UUID constraint[cite: 1]
   */
  @Get(':id')
  async findOne(@Param('id', createUuidV4Pipe()) id: string) {
    return await this.contactService.getContactById(id);
  }

  /**
   * Partial update of a contact
   * Endpoint: POST /contacts/:id[cite: 1]
   * Note: The specification deliberately uses POST for partial updates (The POST double role convention)[cite: 1].
   */
  @Post(':id')
  async update(
    @Param('id', createUuidV4Pipe()) id: string,
    @Body() updateContactDto: UpdateContactDto,
  ) {
    return await this.contactService.updateContact(id, updateContactDto);
  }

  @Delete(':id')
  @HttpCode(HttpStatus.NO_CONTENT)
  remove(@Param('id', createUuidV4Pipe()) id: string): Promise<void> {
    return this.contactService.removeContact(id);
  }
}
import { Injectable } from '@nestjs/common';
import { Brackets, DataSource } from 'typeorm';
import { BaseRepository } from '../../core/database/base.repository';
import {
  buildPaginatedResult,
  resolvePagination,
} from '../../common/utils/pagination.util';
import { DealEntity } from './deal.entity';
import { DealListQueryDto } from './dto';

@Injectable()
export class DealRepository extends BaseRepository<DealEntity> {
  constructor(dataSource: DataSource) {
    super(DealEntity, dataSource.createEntityManager());
  }

  async findWithFilter(query: DealListQueryDto) {
    const { page, pageSize, skip, take } = resolvePagination({
      page: query.page,
      pageSize: query.pageSize,
    });

    const queryBuilder = this.createQueryBuilder('deal');

    if (query.stage) {
      queryBuilder.andWhere('deal.stage = :stage', { stage: query.stage });
    }

    const searchTerm = query.q?.trim();
    if (searchTerm) {
      queryBuilder.andWhere(
        new Brackets((searchQuery) => {
          searchQuery.where('deal.name ILIKE :searchTerm');
        }),
        { searchTerm: `%${searchTerm}%` },
      );
    }

    if (query.companyId) {
      queryBuilder.andWhere('deal.companyId = :companyId', {
        companyId: query.companyId,
      });
    }

    const [items, total] = await queryBuilder
      .orderBy('deal.createdAt', 'DESC')
      .skip(skip)
      .take(take)
      .getManyAndCount();

    return buildPaginatedResult({
      items,
      total,
      page,
      pageSize,
    });
  }
}
import { HttpStatus, Injectable } from '@nestjs/common';
import { AppException } from '../../common/errors/app-exception';
import { BUSINESS_ERROR_CODES } from '../../common/errors/error-codes';
import { CompanyService } from '../company/company.module';
import { ContactService } from '../contact/contact.service';
import { CompanyEntity } from '../company/company.entity';
import { DealRepository } from './deal.repository';
import { DealEntity } from './deal.entity';
import { CreateDealDto, DealListQueryDto, UpdateDealDto } from './dto';

type DealCompanySummary = Pick<
  CompanyEntity,
  'id' | 'name' | 'status' | 'industry'
>;

export type DealDetailResponse = DealEntity & {
  company: DealCompanySummary;
};

@Injectable()
export class DealService {
  constructor(
    private readonly dealRepository: DealRepository,
    private readonly companyService: CompanyService,
    private readonly contactService: ContactService,
  ) {}

  async createDeal(dto: CreateDealDto): Promise<DealEntity> {
    await this.companyService.getCompanyById(dto.companyId);

    const contactId = dto.contactId ?? null;
    if (contactId) {
      await this.validateContactForCompany(contactId, dto.companyId);
    }

    const deal = this.dealRepository.create({
      ...dto,
      contactId,
      expectedCloseDate: dto.expectedCloseDate ?? null,
      stage: dto.stage ?? 'lead',
    });

    return this.dealRepository.save(deal);
  }

  async getDeals(query: DealListQueryDto) {
    return this.dealRepository.findWithFilter(query);
  }

  async getDealById(id: string): Promise<DealDetailResponse> {
    const deal = await this.getDealEntityById(id);
    const company = await this.companyService.getCompanyById(deal.companyId);

    return {
      ...deal,
      company: {
        id: company.id,
        name: company.name,
        status: company.status,
        industry: company.industry,
      },
    };
  }

  async updateDeal(id: string, dto: UpdateDealDto): Promise<DealEntity> {
    if (Object.keys(dto).length === 0) {
      throw new AppException({
        statusCode: HttpStatus.BAD_REQUEST,
        code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
        message: 'At least one field must be provided for update.',
        details: {
          errors: [
            {
              field: 'body',
              messages: ['At least one field must be provided for update.'],
            },
          ],
        },
      });
    }

    const existingDeal = await this.getDealEntityById(id);

    const targetCompanyId = dto.companyId ?? existingDeal.companyId;
    if (dto.companyId && dto.companyId !== existingDeal.companyId) {
      await this.companyService.getCompanyById(dto.companyId);
    }

    const hasContactId = Object.prototype.hasOwnProperty.call(dto, 'contactId');
    const targetContactId = hasContactId
      ? (dto.contactId ?? null)
      : existingDeal.contactId;

    if (targetContactId) {
      await this.validateContactForCompany(targetContactId, targetCompanyId);
    }

    const updatedDeal = this.dealRepository.merge(existingDeal, {
      ...dto,
      contactId: targetContactId,
      stage: dto.stage ?? existingDeal.stage,
      expectedCloseDate: Object.prototype.hasOwnProperty.call(
        dto,
        'expectedCloseDate',
      )
        ? (dto.expectedCloseDate ?? null)
        : existingDeal.expectedCloseDate,
    });

    return this.dealRepository.save(updatedDeal);
  }

  async removeDeal(id: string): Promise<void> {
    await this.getDealEntityById(id);
    await this.dealRepository.softDelete(id);
  }

  private async getDealEntityById(id: string): Promise<DealEntity> {
    const deal = await this.dealRepository.findOne({ where: { id } });

    if (!deal) {
      throw new AppException({
        statusCode: HttpStatus.NOT_FOUND,
        code: BUSINESS_ERROR_CODES.ENTITY_NOT_FOUND,
        message: `Deal with ID ${id} not found`,
        details: {
          resource: 'Deal',
          id,
        },
      });
    }

    return deal;
  }

  private async validateContactForCompany(
    contactId: string,
    companyId: string,
  ): Promise<void> {
    const contact = await this.contactService.getContactById(contactId);

    if (contact.companyId !== companyId) {
      throw new AppException({
        statusCode: HttpStatus.BAD_REQUEST,
        code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
        message: 'contactId must belong to the specified company.',
        details: {
          errors: [
            {
              field: 'contactId',
              messages: ['contactId must belong to the specified company.'],
            },
          ],
        },
      });
    }
  }
}
