  code: BusinessErrorCode;
  message: string;
  details?: unknown;
};

export type AppExceptionPayload = {
  code: BusinessErrorCode;
  message: string;
  details?: unknown;
};

export class AppException extends HttpException {
  constructor(options: AppExceptionOptions) {
    const { statusCode, code, message, details } = options;

