              <TableCell>{companyNameById[deal.companyId] || deal.companyId}</TableCell>
              <TableCell>{deal.contactId || '—'}</TableCell>
              <TableCell align="right">{currencyFormatter.format(Number(deal.value || 0))}</TableCell>
              <StageCell stage={deal.stage} />
              <TableCell>{formatDate(deal.expectedCloseDate)}</TableCell>
              <TableCell>{formatDate(deal.createdAt)}</TableCell>
              <ActionCell deal={deal} onView={onView} onEdit={onEdit} onDelete={onDelete} />
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </TableContainer>
  );
}

import {
  useMutation,
  useQuery,
  useQueryClient,
} from '@tanstack/react-query';

import { contactApi } from '../../api/contactApi';

export const contactKeys = {
  all: ['contacts'],
  lists: () => [...contactKeys.all, 'list'],
  list: (companyId, query) => [...contactKeys.lists(), { companyId: companyId ?? 'all', query }],
  details: () => [...contactKeys.all, 'detail'],
  detail: (contactId) => [...contactKeys.details(), contactId],
};

export function useContactList(params = {}) {
  const { companyId, ...query } = params;
  return useQuery({
    queryKey: contactKeys.list(companyId, query),
    queryFn: () => contactApi.list(companyId, query),
  });
}

export function useContact(id) {
  return useQuery({
    queryKey: contactKeys.detail(id),
    queryFn: () => contactApi.get(id),
    enabled: Boolean(id),
  });
}

export function useCreateContact() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (data) => contactApi.create(data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: contactKeys.lists() });
    },
  });
}

export function useUpdateContact() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ id, data }) => contactApi.update(id, data),
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: contactKeys.lists() });
      queryClient.invalidateQueries({ queryKey: contactKeys.detail(variables.id) });
    },
  });
}

export function useDeleteContact() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (id) => contactApi.delete(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: contactKeys.lists() });
    },
  });
}
