function extractErrorMessage(error, fallbackMessage) {
  return error?.message || fallbackMessage;
}

export default function DealsPage() {
  const navigate = useNavigate();

  const createDeal = useCreateDeal();
  const updateDeal = useUpdateDeal();
  const deleteDeal = useDeleteDeal();

  const [formState, setFormState] = useState({ open: false, mode: 'create', deal: null });
  const [deleteTarget, setDeleteTarget] = useState(null);
  const [feedback, setFeedback] = useState({ open: false, severity: 'success', message: '' });
  const [searchInput, setSearchInput] = useState('');
  const [stageInput, setStageInput] = useState('');
  const [companyInput, setCompanyInput] = useState('');
  const [listQuery, setListQuery] = useState({ page: 1, pageSize: 10 });

  const companiesQuery = useCompanyList({ page: 1, pageSize: 100 });
  const dealsQuery = useDealList(listQuery);

  const companyNameById = useMemo(
    () =>
      Object.fromEntries(
        (companiesQuery.data?.items ?? []).map((company) => [company.id, company.name]),
      ),
    [companiesQuery.data?.items],
  );

  const handleFormSubmit = async (payload) => {
    try {
      if (formState.mode === 'create') {
        await createDeal.mutateAsync(payload);
        setFeedback({
          open: true,
          severity: 'success',
          message: 'Deal created.',
        });
      } else {
        await updateDeal.mutateAsync({
          id: formState.deal.id,
          data: payload,
        });
        setFeedback({
          open: true,
          severity: 'success',
          message: 'Deal updated.',
        });
      }

      setFormState({ open: false, mode: 'create', deal: null });
    } catch (error) {
      if (!isTransportError(error)) {
        setFeedback({
          open: true,
          severity: 'error',
          message: extractErrorMessage(error, 'Deal request failed.'),
        });
      }
    }
  };

  const handleDelete = async () => {
    if (!deleteTarget) {
      return;
    }

    try {
      await deleteDeal.mutateAsync(deleteTarget.id);
      setDeleteTarget(null);
      setFeedback({
        open: true,
        severity: 'success',
        message: 'Deal deleted.',
      });
    } catch (error) {
      if (!isTransportError(error)) {
        setFeedback({
          open: true,
          severity: 'error',
          message: extractErrorMessage(error, 'Delete failed.'),
        });
      }
    }
  };

  const handleSearchSubmit = (event) => {
    event.preventDefault();

    setListQuery((current) => ({
      ...current,
      page: 1,
      ...(searchInput.trim() ? { q: searchInput.trim() } : { q: undefined }),
      ...(stageInput ? { stage: stageInput } : { stage: undefined }),
      ...(companyInput ? { companyId: companyInput } : { companyId: undefined }),
    }));
  };

  const handleResetFilters = () => {
    setSearchInput('');
    setStageInput('');
    setCompanyInput('');
    setListQuery({ page: 1, pageSize: listQuery.pageSize });
  };

  const handlePageChange = (page) => {
    setListQuery((current) => ({ ...current, page }));
  };

  const handlePageSizeChange = (pageSize) => {
    setListQuery((current) => ({ ...current, page: 1, pageSize }));
  };

  const dealPage = dealsQuery.data;
  const dealItems = dealPage?.items ?? [];

  return (
    <Stack spacing={3}>
      <DataTableShell
        title="Deals"
        searchValue={searchInput}
        onSearchChange={setSearchInput}
        onSearchSubmit={handleSearchSubmit}
        onReset={handleResetFilters}
        searchPlaceholder="Search by deal name"
        filters={(
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1}>
            <TextField
              select
              size="small"
              label="Stage"
              value={stageInput}
              onChange={(event) => setStageInput(event.target.value)}
              sx={{ minWidth: '10rem' }}
            >
              <MenuItem value="">All stages</MenuItem>
              <MenuItem value="lead">Lead</MenuItem>
              <MenuItem value="qualified">Qualified</MenuItem>
              <MenuItem value="proposal">Proposal</MenuItem>
              <MenuItem value="negotiation">Negotiation</MenuItem>
              <MenuItem value="won">Won</MenuItem>
              <MenuItem value="lost">Lost</MenuItem>
            </TextField>

            <TextField
              select
              size="small"
              label="Company"
              value={companyInput}
              onChange={(event) => setCompanyInput(event.target.value)}
              sx={{ minWidth: '12rem' }}
            >
              <MenuItem value="">All companies</MenuItem>
              {(companiesQuery.data?.items ?? []).map((company) => (
                <MenuItem key={company.id} value={company.id}>
                  {company.name}
                </MenuItem>
              ))}
            </TextField>
          </Stack>
        )}
        actions={(
          <Button
            variant="contained"
            startIcon={<PlusOutlined />}
            onClick={() => setFormState({ open: true, mode: 'create', deal: null })}
          >
            Add Deal
          </Button>
        )}
        loading={dealsQuery.isLoading}
        error={
          dealsQuery.isError && !isTransportError(dealsQuery.error)
            ? extractErrorMessage(dealsQuery.error, 'Failed to load deals.')
            : null
        }
        isEmpty={!dealsQuery.isLoading && !dealsQuery.isError && dealItems.length === 0}
        emptyTitle="No matching deals"
        emptyDescription="Try broadening the filters or creating a new deal."
        pagination={
          dealPage && dealPage.total > 0 ? (
            <Box sx={{ display: 'flex', width: '100%', justifyContent: 'center' }}>
              <DataTablePagination
                page={dealPage.page}
                pageSize={dealPage.pageSize}
                total={dealPage.total}
                totalPages={dealPage.totalPages}
                onPageChange={handlePageChange}
                onPageSizeChange={handlePageSizeChange}
              />
            </Box>
          ) : null
        }
      >
        <DealTable
          deals={dealItems}
          companyNameById={companyNameById}
          onDelete={setDeleteTarget}
          onEdit={(deal) => setFormState({ open: true, mode: 'edit', deal })}
          onView={(deal) => navigate(`/deals/${deal.id}`)}
        />
      </DataTableShell>

      <DealFormDialog
        open={formState.open}
        mode={formState.mode}
        initialValues={formState.deal}
        isPending={createDeal.isPending || updateDeal.isPending}
        onClose={() => setFormState({ open: false, mode: 'create', deal: null })}
        onSubmit={handleFormSubmit}
      />

      <Dialog open={Boolean(deleteTarget)} onClose={() => setDeleteTarget(null)}>
        <DialogTitle>Delete deal</DialogTitle>
        <DialogContent>
          <Typography>Delete {deleteTarget?.name}? This action cannot be undone.</Typography>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDeleteTarget(null)}>Cancel</Button>
          <Button color="error" variant="contained" onClick={handleDelete}>
            Delete
          </Button>
        </DialogActions>
      </Dialog>

      <Snackbar
        open={feedback.open}
        autoHideDuration={3200}
        onClose={() => setFeedback((current) => ({ ...current, open: false }))}
      >
        <Alert
          onClose={() => setFeedback((current) => ({ ...current, open: false }))}
          severity={feedback.severity}
          variant="filled"
        >
          {feedback.message}
        </Alert>
      </Snackbar>
    </Stack>
  );
}
