import { HttpStatus } from '@nestjs/common';
import { BUSINESS_ERROR_CODES } from '../../common/errors/error-codes';
import { AppException } from '../../common/errors/app-exception';
import { ContactService } from './contact.service';

describe('ContactService', () => {
  const buildService = () => {
    const contactRepository = {
      create: jest.fn(),
      save: jest.fn(),
      findWithFilter: jest.fn(),
      findOne: jest.fn(),
      merge: jest.fn(),
      softDelete: jest.fn(),
    };

    const companyService = {
      getCompanyById: jest.fn(),
    };

    return {
      service: new ContactService(
        contactRepository as never,
        companyService as never,
      ),
      contactRepository,
      companyService,
    };
  };

  it('returns ENTITY_NOT_FOUND when the contact is missing', async () => {
    // Verifies missing contacts return the not-found business error.
    const { service, contactRepository } = buildService();
    contactRepository.findOne.mockResolvedValue(null);

    await expect(service.getContactById('missing-contact')).rejects.toMatchObject(
      {
        status: HttpStatus.NOT_FOUND,
        response: {
          code: BUSINESS_ERROR_CODES.ENTITY_NOT_FOUND,
          details: {
            resource: 'Contact',
            id: 'missing-contact',
          },
        },
      },
    );
  });

  it('fails when moving a contact to a missing company', async () => {
    // Verifies reassignment fails when the target company does not exist.
    const { service, contactRepository, companyService } = buildService();
    contactRepository.findOne.mockResolvedValue({
      id: 'contact-1',
      companyId: 'company-1',
      name: 'Contact One',
    });
    companyService.getCompanyById.mockRejectedValue(
      new AppException({
        statusCode: HttpStatus.NOT_FOUND,
        code: BUSINESS_ERROR_CODES.ENTITY_NOT_FOUND,
        message: 'Company not found',
      }),
    );

    await expect(
      service.updateContact('contact-1', { companyId: 'company-2' }),
    ).rejects.toMatchObject({
      status: HttpStatus.NOT_FOUND,
      response: {
        code: BUSINESS_ERROR_CODES.PARENT_NOT_FOUND,
        details: {
          resource: 'Company',
          id: 'company-2',
        },
      },
    });
    expect(contactRepository.save).not.toHaveBeenCalled();
  });

  it('saves the updated contact when the target company exists', async () => {
    // Verifies reassignment succeeds when the target company is valid.
    const { service, contactRepository, companyService } = buildService();
    const existingContact = {
      id: 'contact-2',
      companyId: 'company-1',
      role: 'User',
    };
    const mergedContact = {
      ...existingContact,
      companyId: 'company-3',
      role: 'Decision Maker',
    };

    contactRepository.findOne.mockResolvedValue(existingContact);
    companyService.getCompanyById.mockResolvedValue({ id: 'company-3' });
    contactRepository.merge.mockReturnValue(mergedContact);
    contactRepository.save.mockResolvedValue(mergedContact);

    await expect(
      service.updateContact('contact-2', {
        companyId: 'company-3',
        role: 'Decision Maker',
      }),
    ).resolves.toEqual(mergedContact);
  });
});
import { HttpStatus } from '@nestjs/common';
import { BUSINESS_ERROR_CODES } from '../../common/errors/error-codes';
import { CompanyService } from './company.service';

describe('CompanyService', () => {
  const createQueryBuilder = () => ({
    from: jest.fn().mockReturnThis(),
    where: jest.fn().mockReturnThis(),
    andWhere: jest.fn().mockReturnThis(),
    getCount: jest.fn(),
  });

  const buildService = () => {
    const queryBuilder = createQueryBuilder();
    const companyRepo = {
      create: jest.fn(),
      save: jest.fn(),
      findWithFilter: jest.fn(),
      findOne: jest.fn(),
      merge: jest.fn(),
      softDelete: jest.fn(),
      manager: {
        createQueryBuilder: jest.fn().mockReturnValue(queryBuilder),
      },
    };

    return {
      service: new CompanyService(companyRepo as never),
      companyRepo,
      queryBuilder,
    };
  };

  it('returns ENTITY_NOT_FOUND when the company is missing', async () => {
    // Verifies missing companies return the not-found business error.
    const { service, companyRepo } = buildService();
    companyRepo.findOne.mockResolvedValue(null);

    await expect(service.getCompanyById('missing-id')).rejects.toMatchObject({
      status: HttpStatus.NOT_FOUND,
      response: {
        code: BUSINESS_ERROR_CODES.ENTITY_NOT_FOUND,
        details: {
          resource: 'Company',
          id: 'missing-id',
        },
      },
    });
  });

  it('blocks delete when the company still has contacts', async () => {
    // Verifies delete is blocked when related contacts still exist.
    const { service, companyRepo, queryBuilder } = buildService();
    companyRepo.findOne.mockResolvedValue({ id: 'company-1' });
    queryBuilder.getCount.mockResolvedValueOnce(2).mockResolvedValueOnce(0);

    await expect(service.removeCompany('company-1')).rejects.toMatchObject({
      status: HttpStatus.CONFLICT,
      response: {
        code: BUSINESS_ERROR_CODES.REFERENTIAL_INTEGRITY_VIOLATION,
        details: {
          resource: 'Company',
          id: 'company-1',
          blockingChildren: {
            contacts: 2,
            deals: 0,
          },
        },
      },
    });
    expect(companyRepo.softDelete).not.toHaveBeenCalled();
  });

  it('soft deletes when the company has no contacts', async () => {
    // Verifies delete succeeds when no related contacts remain.
    const { service, companyRepo, queryBuilder } = buildService();
    companyRepo.findOne.mockResolvedValue({ id: 'company-2' });
    queryBuilder.getCount.mockResolvedValue(0);

    await service.removeCompany('company-2');

    expect(companyRepo.softDelete).toHaveBeenCalledWith('company-2');
  });
});

import { faker } from '@faker-js/faker';
import { ContactEntity } from '../../../modules/contact/contact.entity';

type BuildContactInput = {
  companyId: string;
  name: string;
  lastContactedAt?: Date;
  email?: string | null;
  phone?: string | null;
  role?: string | null;
};

const buildPhoneNumber = () =>
  `+1-${faker.string.numeric(3)}-${faker.string.numeric(3)}-${faker.string.numeric(4)}`;

export const buildContact = ({
  companyId,
  name,
  lastContactedAt,
  email,
  phone,
  role,
}: BuildContactInput): Partial<ContactEntity> => {
  const contact: Partial<ContactEntity> = {
    companyId,
    name,
  };

  if (email !== null) {
    contact.email =
      email ?? faker.internet.email({ firstName: name.split(' ')[0] });
  }

  if (phone !== null) {
    contact.phone = phone ?? buildPhoneNumber();
  }

  if (role !== null) {
    contact.role =
      role ??
      faker.helpers.arrayElement([
        'Decision Maker',
        'Champion',
        'Evaluator',
        'Procurement',
      ]);
  }

  if (lastContactedAt !== undefined) {
    contact.lastContactedAt = lastContactedAt;
  }

  return contact;
};
