    expect(invalidResponse.body).toMatchObject({
      success: false,
      statusCode: 400,
      code: 'INVALID_UUID',
    });

    const missingResponse = await request(app.getHttpServer())
      .get('/api/companies/7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1aa')
