import { HttpStatus, ValidationError } from '@nestjs/common';
import { AppException } from './app-exception';
import { BUSINESS_ERROR_CODES } from './error-codes';

type FormattedValidationError = {
  field: string;
  messages: string[];
};

export function createValidationException(errors: ValidationError[]) {
  const formattedErrors = flattenValidationErrors(errors);
  const firstMessage =
    formattedErrors[0]?.messages[0] ?? 'Request validation failed.';

  return new AppException({
    statusCode: HttpStatus.BAD_REQUEST,
    code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
    message: firstMessage,
    details: {
      errors: formattedErrors,
    },
  });
}

function flattenValidationErrors(
  errors: ValidationError[],
  parentPath?: string,
): FormattedValidationError[] {
  return errors.flatMap((error) => {
    const field = parentPath
      ? `${parentPath}.${error.property}`
      : error.property;
    const messages = error.constraints ? Object.values(error.constraints) : [];
    const currentError = messages.length > 0 ? [{ field, messages }] : [];
    const childErrors = error.children
      ? flattenValidationErrors(error.children, field)
      : [];

    return [...currentError, ...childErrors];
  });
}

import { Repository, FindManyOptions, ObjectLiteral } from 'typeorm';
import {
  resolvePagination,
  buildPaginatedResult,
} from '../../common/utils/pagination.util';

export class BaseRepository<T extends ObjectLiteral> extends Repository<T> {
  /**
   * Execute a paginated query using standardized pagination utilities
   *
   * @param page The current page number (starts from 1)
   * @param limit The number of items per page
   * @param options Additional TypeORM query options
   */
  async paginate(
    page: number | string = 1,
    limit: number | string = 10,
    options?: FindManyOptions<T>,
  ) {
    const {
      page: validPage,
      pageSize: validLimit,
      skip,
      take,
    } = resolvePagination({
      page,
      pageSize: limit,
    });

    const [items, total] = await this.findAndCount({
      ...options,
      skip,
      take,
    });

    return buildPaginatedResult({
      items,
      total,
      page: validPage,
      pageSize: validLimit,
    });
  }
}

