type ContactCompanySummary = {
  id: string;
  name: string;
  status: string;
  industry: string | null;
};

export type ContactCompanyLinkResponse = {
  companyId: string;
  isPrimary: boolean;
  company: ContactCompanySummary | null;
};

export type ContactResponse = ContactEntity & {
  primaryCompanyId: string | null;
  companyLinks: ContactCompanyLinkResponse[];
};

type NormalizedCompanyLink = {
  companyId: string;
  isPrimary: boolean;
};

type ContactCompanyLinkRow = {
  contactId: string;
  companyId: string;
  isPrimary: boolean;
  companyIdValue: string | null;
  companyName: string | null;
  companyStatus: string | null;
  companyIndustry: string | null;
};

@Injectable()
export class ContactService {
  constructor(
    private readonly contactRepository: ContactRepository,
    private readonly companyService: CompanyService,
  ) {}

  async createContact(dto: CreateContactDto): Promise<ContactResponse> {
    const companyLinks = this.resolveCreateCompanyLinks(dto);
    await this.validateCompaniesExist(companyLinks.map((link) => link.companyId));

    const { companyId, companyIds, primaryCompanyId, ...contactFields } = dto;

    const savedContact = await this.contactRepository.manager.transaction(
      async (entityManager) => {
        const contactRepository = entityManager.getRepository(ContactEntity);

        const contact = contactRepository.create({
          ...contactFields,
          role: contactFields.role ?? null,
          lastContactedAt: contactFields.lastContactedAt ?? null,
        });

        const persistedContact = await contactRepository.save(contact);

        await entityManager
          .createQueryBuilder()
          .insert()
          .into('contact_companies')
          .values(
            companyLinks.map((link) => ({
              contactId: persistedContact.id,
              companyId: link.companyId,
              isPrimary: link.isPrimary,
            })),
          )
          .execute();

        return persistedContact;
      },
    );

    return this.getContactById(savedContact.id);
  }

  async getContactsList(query: ContactListQueryDto) {
    const [items, total] = await this.contactRepository.findWithFilter(query);
    const contacts = await this.buildContactResponses(items);

    const limit = query.pageSize ?? 20;
    const page = query.page ?? 1;

    return {
      items: contacts,
      total,
      page,
      pageSize: limit,
      totalPages: Math.ceil(total / limit),
    };
  }

  async getContactById(id: string): Promise<ContactResponse> {
    const contact = await this.getContactEntityById(id);
    const contacts = await this.buildContactResponses([contact]);
    return contacts[0];
  }

  async getContactEntityById(id: string): Promise<ContactEntity> {
    const contact = await this.contactRepository.findOne({ where: { id } });

    if ("'!contact) {
      throw new AppException({
        statusCode: HttpStatus.NOT_FOUND,
        code: BUSINESS_ERROR_CODES.ENTITY_NOT_FOUND,
        message: `Contact with ID ${id} not found`,
        details: {
          resource: '"'Contact',
          id,
        },
      });
    }

    return contact;
  }

  async isContactLinkedToCompany(
    contactId: string,
    companyId: string,
  ): Promise<boolean> {
    const row = await this.contactRepository.manager
      .createQueryBuilder()
      .from('contact_companies', 'contactCompany')
      .innerJoin(
        'contacts',
        'contact',
        'contact.id = contactCompany.\"contactId\" AND contact.\"deletedAt\" IS NULL',
      )
      .select('1', 'linked')
      .where('contactCompany.\"contactId\" = :contactId', { contactId })
      .andWhere('contactCompany.\"companyId\" = :companyId', { companyId })
      .limit(1)
      .getRawOne<{ linked: number } | undefined>();

    return Boolean(row);
  }

  async updateContact(id: string, dto: UpdateContactDto): Promise<ContactResponse> {
    const contact = await this.getContactEntityById(id);
    const currentLinks = await this.getRawCompanyLinksByContactIds([id]);

    const hasLinkMutation =
      Object.prototype.hasOwnProperty.call(dto, 'companyId') ||
      Object.prototype.hasOwnProperty.call(dto, 'companyIds') ||
      Object.prototype.hasOwnProperty.call(dto, 'primaryCompanyId') ||
      Object.prototype.hasOwnProperty.call(dto, 'companyLinks');

    const nextLinks = hasLinkMutation
      ? this.resolveUpdatedCompanyLinks(dto, currentLinks[id] ?? [])
      : null;

    if (nextLinks) {
      await this.validateCompaniesExist(nextLinks.map((link) => link.companyId));
    }

    const {
      companyId,
      companyIds,
      primaryCompanyId,
      companyLinks,
      ...contactPatch
    } = dto;

    await this.contactRepository.manager.transaction(async (entityManager) => {
      const contactRepository = entityManager.getRepository(ContactEntity);

      const updatedContact = contactRepository.merge(contact, {
        ...contactPatch,
        role: Object.prototype.hasOwnProperty.call(contactPatch, 'role')
