    const targetCompanyId = dto.companyId ?? existingDeal.companyId;
    if (dto.companyId && dto.companyId !== existingDeal.companyId) {
      await this.companyService.getCompanyById(dto.companyId);
    }

    const hasContactId = Object.prototype.hasOwnProperty.call(dto, 'contactId');
    const targetContactId = hasContactId
      ? (dto.contactId ?? null)
      : existingDeal.contactId;

    if (targetContactId) {
