    if ("'!isFormValid) {
      return;
    }

    await onSubmit({
      companyId: values.companyId,
      name: values.name.trim(),
      value: Number(values.value),
      stage: values.stage,
      expectedCloseDate: values.expectedCloseDate
        ? new Date(values.expectedCloseDate).toISOString()
        : null,
      primaryContactId: values.primaryContactId || null,
      contactLinks: values.contactLinks.map((link) => ({
        contactId: link.contactId,
        role: link.role?.trim() || null,
      })),
    });
  };

  return (
    <Dialog open={open} onClose={isPending ? undefined : onClose} fullWidth maxWidth="sm">
      <DialogTitle>{mode === '"'create' ? 'Create deal' : 'Edit deal'}</DialogTitle>

      <DialogContent sx={{ p: 2.5 }}>
        <Stack component=\"form\" spacing={2} onSubmit={handleSubmit} sx={{ mt: 1 }}>
          <TextField
            required
            autoFocus
            label=\"Name\"
            value={values.name}
            onChange={handleChange('name')}
            onBlur={handleBlur('name')}
            error={touched.name && Boolean(errors.name)}
            helperText={touched.name ? errors.name : undefined}
          />

          <Autocomplete
            fullWidth
            options={companyOptions}
            value={selectedCompany}
            loading={companiesQuery.isLoading}
            onBlur={handleBlur('companyId')}
            onChange={handleCompanyChange}
            isOptionEqualToValue={(option, value) => option.id === value.id}
            getOptionLabel={(option) => option?.name || ''}
            noOptionsText={companiesQuery.isLoading ? 'Loading companies...' : 'No companies found'}
            renderInput={(params) => (
              <TextField
                {...params}
                required
                label=\"Company\"
                error={touched.companyId && Boolean(errors.companyId)}
                helperText={
                  touched.companyId
                    ? errors.companyId
                    : companiesQuery.isError
                      ? 'Failed to load companies.'
                      : undefined
                }
                InputProps={{
                  ...params.InputProps,
                  endAdornment: (
                    <>
                      {companiesQuery.isLoading ? <CircularProgress color=\"inherit\" size={20} /> : null}
                      {params.InputProps.endAdornment}
                    </>
                  ),
                }}
              />
            )}
          />

          <Autocomplete
            multiple
            fullWidth
            options={mergedContactOptions}
            value={selectedContacts}
            loading={contactsQuery.isLoading}
            onChange={handleContactsChange}
            isOptionEqualToValue={(option, value) => option.id === value.id}
            getOptionLabel={(option) => option?.name || ''}
            noOptionsText={
              values.companyId
                ? contactsQuery.isLoading
                  ? 'Loading contacts...'
                  : 'No contacts found for this company'
                : 'Select a company first'
            }
            disabled={"'!values.companyId}
            renderInput={(params) => (
              <TextField
                {...params}
                label="Linked Contacts"
                helperText={contactsQuery.isError ? '"'Failed to load contacts.' : undefined}
                InputProps={{
                  ...params.InputProps,
                  endAdornment: (
                    <>
                      {contactsQuery.isLoading && values.companyId ? (
                        <CircularProgress color=\"inherit\" size={20} />
                      ) : null}
                      {params.InputProps.endAdornment}
                    </>
                  ),
                }}
              />
            )}
          />

          <TextField
            fullWidth
            select
            label=\"Primary Contact (optional)\"
            value={values.primaryContactId}
            onBlur={handleBlur('primaryContactId')}
            onChange={handleChange('primaryContactId')}
            error={touched.primaryContactId && Boolean(errors.primaryContactId)}
            helperText={touched.primaryContactId ? errors.primaryContactId : undefined}
            disabled={values.contactLinks.length === 0}
          >
            <MenuItem value=\"\">None</MenuItem>
            {values.contactLinks.map((link) => (
              <MenuItem key={link.contactId} value={link.contactId}>
                {link.contactName || link.contactId}
              </MenuItem>
            ))}
          </TextField>

          {values.contactLinks.map((link) => (
            <TextField
              key={link.contactId}
              fullWidth
              label={"'`${link.contactName || link.contactId} role (optional)`}
              value={link.role || '"''}
              onChange={(event) =>
                handleContactRoleChange(link.contactId, event.target.value)
