import { BUSINESS_ERROR_CODES } from '../../common/errors/error-codes';
import { AppException } from '../../common/errors/app-exception';
import { ContactService } from './contact.service';

describe('ContactService', () => {
  const createRawQueryBuilder = () => ({
    from: jest.fn().mockReturnThis(),
    innerJoin: jest.fn().mockReturnThis(),
    leftJoin: jest.fn().mockReturnThis(),
    select: jest.fn().mockReturnThis(),
    addSelect: jest.fn().mockReturnThis(),
    where: jest.fn().mockReturnThis(),
    andWhere: jest.fn().mockReturnThis(),
    orderBy: jest.fn().mockReturnThis(),
    addOrderBy: jest.fn().mockReturnThis(),
    limit: jest.fn().mockReturnThis(),
    getRawOne: jest.fn(),
    getRawMany: jest.fn(),
  });

  const buildService = () => {
    const queryBuilder = createRawQueryBuilder();

    const contactRepository = {
      create: jest.fn(),
      save: jest.fn(),
      findWithFilter: jest.fn(),
      findOne: jest.fn(),
      merge: jest.fn(),
      softDelete: jest.fn(),
      manager: {
        createQueryBuilder: jest.fn().mockReturnValue(queryBuilder),
        transaction: jest.fn(),
      },
    };

    const companyService = {
      getCompanyById: jest.fn(),
    };

    return {
      service: new ContactService(
        contactRepository as never,
        companyService as never,
      ),
      contactRepository,
      companyService,
      queryBuilder,
    };
  };

  it('returns ENTITY_NOT_FOUND when the contact is missing', async () => {
    const { service, contactRepository } = buildService();
    contactRepository.findOne.mockResolvedValue(null);

    await expect(
      service.getContactEntityById('missing-contact'),
    ).rejects.toMatchObject({
      status: HttpStatus.NOT_FOUND,
      response: {
        code: BUSINESS_ERROR_CODES.ENTITY_NOT_FOUND,
        details: {
          resource: 'Contact',
          id: 'missing-contact',
        },
      },
    });
  });

  it('fails when attaching an unknown company through legacy companyId', async () => {
    const { service, contactRepository, companyService, queryBuilder } = buildService();

    contactRepository.findOne.mockResolvedValue({
      id: 'contact-1',
      name: 'Contact One',
      role: null,
      lastContactedAt: null,
    });

    queryBuilder.getRawMany.mockResolvedValue([
      {
        contactId: 'contact-1',
        companyId: 'company-1',
        isPrimary: true,
        companyIdValue: 'company-1',
        companyName: 'Company One',
        companyStatus: '1',
        companyIndustry: null,
      },
    ]);

    companyService.getCompanyById.mockRejectedValue(
      new AppException({
        statusCode: HttpStatus.NOT_FOUND,
        code: BUSINESS_ERROR_CODES.ENTITY_NOT_FOUND,
        message: 'Company not found',
      }),
    );

    await expect(
      service.updateContact('contact-1', { companyId: 'company-2' }),
    ).rejects.toMatchObject({
      status: HttpStatus.NOT_FOUND,
      response: {
        code: BUSINESS_ERROR_CODES.PARENT_NOT_FOUND,
        details: {
          resource: 'Company',
          id: 'company-2',
        },
      },
    });

    expect(contactRepository.manager.transaction).not.toHaveBeenCalled();
  });

  it('rejects companyLinks payloads without a primary company', async () => {
    const { service, contactRepository, queryBuilder } = buildService();

    contactRepository.findOne.mockResolvedValue({
      id: 'contact-2',
      name: 'Contact Two',
      role: null,
      lastContactedAt: null,
    });

    queryBuilder.getRawMany.mockResolvedValue([
      {
        contactId: 'contact-2',
        companyId: 'company-1',
        isPrimary: true,
        companyIdValue: 'company-1',
        companyName: 'Company One',
        companyStatus: '1',
        companyIndustry: null,
      },
    ]);

    await expect(
      service.updateContact('contact-2', {
        companyLinks: [{ companyId: 'company-2', isPrimary: false }],
      }),
    ).rejects.toMatchObject({
      status: HttpStatus.CONFLICT,
      response: {
        code: BUSINESS_ERROR_CODES.INVALID_LINK_STATE,
      },
    });
  });
});
